#!/usr/bin/env bash
# Galerie publique : les disciplines dans l'ordre du menu « Nos disciplines ».
# Prérequis : apply-docs-garde-edge.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-ordre-disciplines.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/app-shell/disciplineOrder.ts" 2>/dev/null | grep -qF "export function compareDisciplines"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "qui appelle lib/devTargetGuard.ts" "apps/web/content/docs/dev/demarrer/mise-en-route.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-garde-edge.sh"; exit 1; }
MODIFIED=("apps/web/src/features/app-shell/OurActivitiesMenu.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/gallery-public/GalleryGroupedView.tsx" "e2e/data.mjs" "e2e/prepare.mjs" "packages/backend/src/modules/galleries/router.ts")
EXPECT=("93aea1a54bd4:apps/web/src/features/app-shell/OurActivitiesMenu.tsx" "a2175ff8c1ac:apps/web/src/features/docs/entities/procedureMap.generated.json" "98a6690080e2:apps/web/src/features/gallery-public/GalleryGroupedView.tsx" "6501407dc7ab:e2e/data.mjs" "72658213f9f2:e2e/prepare.mjs" "61114c4d5a15:packages/backend/src/modules/galleries/router.ts")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/src/features/app-shell/disciplineOrder.ts" "e2e/galerie-ordre.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function compareDisciplines" "apps/web/src/features/app-shell/disciplineOrder.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

